#include "lmcpp/lmcpp.hpp"
#include <algorithm>
#include <iostream>
#include <sstream>
#include <stdexcept>

namespace lmcpp {
static const char* type_name(Type t) { switch(t){case Type::String:return "string";case Type::Number:return "number";case Type::Integer:return "integer";case Type::Boolean:return "boolean";} return "string"; }
static int exit_for(ErrorCode c) { switch(c){case ErrorCode::InvalidRequest:case ErrorCode::ValidationError:return 2;case ErrorCode::ParseError:return 3;case ErrorCode::NotFound:return 4;case ErrorCode::Conflict:return 5;case ErrorCode::Forbidden:return 6;case ErrorCode::Timeout:return 7;case ErrorCode::ServiceUnavailable:return 8;case ErrorCode::MissingConfirmation:return 9;case ErrorCode::UnsupportedProductVersion:return 10;default:return 1;} }
static std::string code_name(ErrorCode c) { switch(c){case ErrorCode::InvalidRequest:return "INVALID_REQUEST";case ErrorCode::ValidationError:return "VALIDATION_ERROR";case ErrorCode::ParseError:return "PARSE_ERROR";case ErrorCode::NotFound:return "NOT_FOUND";case ErrorCode::Conflict:return "CONFLICT";case ErrorCode::Forbidden:return "FORBIDDEN";case ErrorCode::Timeout:return "TIMEOUT";case ErrorCode::ServiceUnavailable:return "SERVICE_UNAVAILABLE";case ErrorCode::MissingConfirmation:return "MISSING_CONFIRMATION";case ErrorCode::UnsupportedProductVersion:return "UNSUPPORTED_PRODUCT_VERSION";case ErrorCode::InternalError:return "INTERNAL_ERROR";case ErrorCode::CommandFailed:return "COMMAND_FAILED";} return "UNKNOWN_ERROR"; }
static Json param_json(const Param& p) { Json j={{"name",p.name},{"type",type_name(p.type)},{"occurs",p.occurs}}; if(!p.required) j["occurs"]="?"; if(!p.default_value.is_null()) j["default"]=p.default_value; if(!p.enum_values.empty()) j["enum"]=p.enum_values; if(!p.description.empty())j["description"]=p.description; return j; }
Json publish_schema(const CliSpec& s) { Json ops=Json::array(); for(const auto& o:s.operations){Json ps=Json::array();for(const auto&p:o.params)ps.push_back(param_json(p));ops.push_back({{"name",o.name},{"access",o.access==Access::Read?"read":"write"},{"returns",o.returns},{"description",o.description},{"params",ps}});} return {{"schema","cli.schema.v1"},{"tool",s.tool},{"version",s.version},{"inputs",{"flags","json"}},{"globals",Json::array()},{"operations",ops}}; }
static const Operation& find_op(const CliSpec&s,const std::string& n){for(const auto&o:s.operations)if(o.name==n)return o;throw Error{ErrorCode::InvalidRequest,"unknown operation: "+n,{{"op",n}}};}
static Json validate(const Operation&o,const Json& raw){Json result=Json::object(), issues=Json::array();for(auto it=raw.begin();it!=raw.end();++it){bool known=false;for(auto&p:o.params)known|=p.name==it.key();if(!known)issues.push_back({{"code","UNKNOWN_PARAM"},{"param",it.key()},{"message","unknown parameter: "+it.key()}});} for(const auto&p:o.params){auto it=raw.find(p.name);if(it==raw.end()){if(p.required&&p.default_value.is_null())issues.push_back({{"code","MISSING_REQUIRED"},{"param",p.name},{"message","missing required parameter: "+p.name}});else if(!p.default_value.is_null())result[p.name]=p.default_value;continue;}const Json&v=*it;bool ok=false;switch(p.type){case Type::String:ok=v.is_string();break;case Type::Number:ok=v.is_number();break;case Type::Integer:ok=v.is_number_integer();break;case Type::Boolean:ok=v.is_boolean();break;}if(!ok){issues.push_back({{"code","TYPE_MISMATCH"},{"param",p.name},{"message","invalid type for parameter: "+p.name}});continue;}if(!p.enum_values.empty()&&std::find(p.enum_values.begin(),p.enum_values.end(),v)==p.enum_values.end()){issues.push_back({{"code","ENUM_VIOLATION"},{"param",p.name},{"message","invalid enum value for parameter: "+p.name}});continue;}result[p.name]=v;}if(!issues.empty())throw Error{ErrorCode::ValidationError,"invalid arguments for \""+o.name+"\"",{{"op",o.name},{"issues",issues}}};return result;}
Resolved resolve_input(const CliSpec&s,const std::vector<std::string>& a){if(a.empty())throw Error{ErrorCode::InvalidRequest,"missing operation name"};const auto&o=find_op(s,a[0]);Json raw=Json::object();bool json_form=false;for(size_t i=1;i<a.size();++i){auto token=a[i];if(token=="--input-json"){if(json_form||!raw.empty())throw Error{ErrorCode::ValidationError,"cannot mix input forms"};if(++i==a.size())throw Error{ErrorCode::ValidationError,"missing value for --input-json"};try{Json doc=Json::parse(a[i]);json_form=true;if(doc.is_object()&&doc.contains("op")&&doc.contains("params")){if(doc["op"]!=o.name)throw Error{ErrorCode::ValidationError,"operation mismatch",{{"op",doc["op"]}}};raw=doc["params"];}else raw=doc;}catch(const Error&){throw;}catch(...){throw Error{ErrorCode::ParseError,"malformed JSON input"};}continue;}if(json_form)throw Error{ErrorCode::ValidationError,"cannot mix JSON with operation flags"};if(token.rfind("--",0)!=0)throw Error{ErrorCode::InvalidRequest,"invalid argument: "+token};auto eq=token.find('=');std::string name=token.substr(2,eq==std::string::npos?std::string::npos:eq-2);const Param*p=nullptr;for(auto&x:o.params)if(x.name==name)p=&x;if(!p)throw Error{ErrorCode::ValidationError,"unknown parameter: "+name,{{"issues",Json::array({Json{{"code","UNKNOWN_PARAM"},{"param",name},{"message","unknown parameter: "+name}}})}}};if(raw.contains(name))throw Error{ErrorCode::ValidationError,"duplicate parameter: "+name,{{"issues",Json::array({Json{{"code","DUPLICATE_FLAG"},{"param",name},{"message","duplicate parameter: "+name}}})}}};if(p->type==Type::Boolean&&eq==std::string::npos){raw[name]=true;continue;}std::string value;if(eq!=std::string::npos)value=token.substr(eq+1);else if(++i<a.size())value=a[i];else throw Error{ErrorCode::ValidationError,"missing value for --"+name};try{raw[name]=Json::parse(value);}catch(...){raw[name]=value;}}return{o.name,validate(o,raw)};}
int run_cli_io(const CliSpec&s,const std::vector<std::string>&a,std::ostream&out,std::ostream&err){try{if(a.size()==1&&a[0]=="--schema"){out<<publish_schema(s).dump(2)<<'\n';return 0;}auto r=resolve_input(s,a);const auto&o=find_op(s,r.op);if(!o.handler)throw Error{ErrorCode::InternalError,"operation has no handler"};out<<o.handler(r.params).dump()<<'\n';return 0;}catch(const Error&e){out<<Json{{"success",false},{"error",{{"code",code_name(e.code)},{"message",e.message},{"data",e.data}}}}.dump(2)<<'\n';return exit_for(e.code);}catch(const std::exception&e){err<<e.what()<<'\n';out<<Json{{"success",false},{"error",{{"code","INTERNAL_ERROR"},{"message",e.what()},{"data",Json::object()}}}}.dump(2)<<'\n';return 1;}catch(...){out<<"{\"success\":false,\"error\":{\"code\":\"INTERNAL_ERROR\",\"message\":\"unknown exception\",\"data\":{}}}\n";return 1;}}
int run_cli(const CliSpec&s,int argc,char**argv){std::vector<std::string>a;for(int i=1;i<argc;++i)a.emplace_back(argv[i]);return run_cli_io(s,a,std::cout,std::cerr);}
}
